   133→// BlobRPCMinValidSlot returns the lowest slot that we should expect peers to respect as the
   134→// start slot in a BlobSidecarsByRange request. This can be used to validate incoming requests and
   135→// to avoid pestering peers with requests for blobs that are outside the retention window.
   136→func BlobRPCMinValidSlot(current primitives.Slot) (primitives.Slot, error) {
   137→	// Avoid overflow if we're running on a config where deneb is set to far future epoch.
   138→	if params.BeaconConfig().DenebForkEpoch == math.MaxUint64 {
   139→		return primitives.Slot(math.MaxUint64), nil
   140→	}
   141→	minReqEpochs := params.BeaconConfig().MinEpochsForBlobsSidecarsRequest
   142→	currEpoch := slots.ToEpoch(current)
   143→	minStart := params.BeaconConfig().DenebForkEpoch
   144→	if currEpoch > minReqEpochs && currEpoch-minReqEpochs > minStart {
   145→		minStart = currEpoch - minReqEpochs
   146→	}
   147→	return slots.EpochStart(minStart)
   148→}
   149→
   150→// This function is used to derive what is the ideal block batch size we can serve
   151→// blobs to the remote peer for. We compute the current limit which is the maximum
   152→// blobs to be served to the peer every period. And then using the maximum blobs per
   153→// block determine the block batch size satisfying this limit.
   154→func blobBatchLimit(slot primitives.Slot) uint64 {
   155→	maxBlobsPerBlock := params.BeaconConfig().MaxBlobsPerBlock(slot)
   156→	maxPossibleBlobs := flags.Get().BlobBatchLimit * flags.Get().BlobBatchLimitBurstFactor
   157→	return uint64(maxPossibleBlobs / maxBlobsPerBlock)
   158→}
   159→
   160→func validateBlobsByRange(r *pb.BlobSidecarsByRangeRequest, current primitives.Slot) (rangeParams, error) {
   161→	if r.Count == 0 {
   162→		return rangeParams{}, errors.Wrap(p2ptypes.ErrInvalidRequest, "invalid request Count parameter")
   163→	}
   164→	rp := rangeParams{
   165→		start: r.StartSlot,
   166→		size:  r.Count,
   167→	}
   168→	// Peers may overshoot the current slot when in initial sync, so we don't want to penalize them by treating the
   169→	// request as an error. So instead we return a set of params that acts as a noop.
   170→	if rp.start > current {
   171→		return rangeParams{start: current, end: current, size: 0}, nil
   172→	}
   173→
   174→	var err error
   175→	rp.end, err = rp.start.SafeAdd(rp.size - 1)
   176→	if err != nil {
   177→		return rangeParams{}, errors.Wrap(p2ptypes.ErrInvalidRequest, "overflow start + count -1")
   178→	}
   179→
   180→	maxRequest := params.MaxRequestBlock(slots.ToEpoch(current))
   181→	// Allow some wiggle room, up to double the MaxRequestBlocks past the current slot,
   182→	// to give nodes syncing close to the head of the chain some margin for error.
   183→	maxStart, err := current.SafeAdd(maxRequest * 2)
   184→	if err != nil {
   185→		return rangeParams{}, errors.Wrap(p2ptypes.ErrInvalidRequest, "current + maxRequest * 2 > max uint")
   186→	}
   187→
   188→	// Clients MUST keep a record of signed blobs sidecars seen on the epoch range
   189→	// [max(current_epoch - MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS, DENEB_FORK_EPOCH), current_epoch]
   190→	// where current_epoch is defined by the current wall-clock time,
   191→	// and clients MUST support serving requests of blobs on this range.
   192→	minStartSlot, err := BlobRPCMinValidSlot(current)
   193→	if err != nil {
   194→		return rangeParams{}, errors.Wrap(p2ptypes.ErrInvalidRequest, "BlobRPCMinValidSlot error")
   195→	}
   196→	if rp.start > maxStart {
   197→		return rangeParams{}, errors.Wrap(p2ptypes.ErrInvalidRequest, "start > maxStart")
   198→	}
   199→	if rp.start < minStartSlot {
   200→		rp.start = minStartSlot
   201→	}
   202→
   203→	if rp.end > current {
   204→		rp.end = current
   205→	}
   206→	if rp.end < rp.start {
   207→		rp.end = rp.start
   208→	}
   209→
   210→	limit := blobBatchLimit(current)
   211→	if limit > maxRequest {
   212→		limit = maxRequest
   213→	}
   214→	if rp.size > limit {
   215→		rp.size = limit
   216→	}
   217→
   218→	return rp, nil
   219→}
